effect.shader:
/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Soft-light (CSS/SVG definition): preserva contraste melhor que mix normal. */
vec3 softLight(vec3 baixa, vec3 alta) {
    vec3 d = mix(sqrt(baixa) * (2.0 * alta - 1.0) + 2.0 * baixa * (1.0 - alta),
                 2.0 * baixa * alta + baixa * baixa * (1.0 - 2.0 * alta),
                 step(alta, vec3(0.5)));
    return d;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float L = luma(original.rgb);

    // Forças: alta em sombras pra cor de sombra, alta em luzes pra cor de luz.
    float forcaSombra = (1.0 - smoothstep(0.0, balance, L)) * shadowAmount;
    float forcaLuz = smoothstep(balance, 1.0, L) * highlightAmount;

    // Cada ponta pinta por soft-light; a mistura entre elas é por força.
    vec3 comSombra = softLight(original.rgb, shadowColor.rgb);
    vec3 comLuz = softLight(original.rgb, highlightColor.rgb);

    vec3 cor = original.rgb;
    cor = mix(cor, comSombra, forcaSombra * shadowColor.a);
    cor = mix(cor, comLuz, forcaLuz * highlightColor.a);

    fragColor = vec4(cor, original.a);
}
